     */
    public Optional<Incident> lockByKey(String incidentKey) {
        List<Incident> rows = jdbc.query("SELECT * FROM incidents WHERE incident_key = ? FOR UPDATE",
                INCIDENT_MAPPER, incidentKey);
        return rows.stream().findFirst();
