            ps.setString(4, transfer.status().name());
            ps.setTimestamp(5, Timestamp.from(transfer.createdAt()));
            ps.setTimestamp(6, transfer.acceptedAt() == null ? null : Timestamp.from(transfer.acceptedAt()));
            return ps;
        }, keys);
        return keys.getKey().longValue();
