68	    private IncidentView setup(String incidentKey, String severity, String commander) {
69	        service.report(new ReportRequest(incidentKey, severity, "核心链路故障", "reporter-1"));
70	        return service.takeover(incidentKey, commander, new TakeoverRequest(key()));
