78	    @Test
79	    void deadline_setAtTakeover_bySeverity_andNotResetByTransfer() {
80	        Map<String, Long> minutes = Map.of("S1", 5L, "S2", 15L, "S3", 60L, "S4", 240L);
81	        int n = 0;
82	        for (Map.Entry<String, Long> e : minutes.entrySet()) {
83	            String ik = "INC-DL-" + n++;
84	            IncidentView commanding = setup(ik, e.getKey(), "alice");
85	            Instant expected = T0.plus(e.getValue(), ChronoUnit.MINUTES);
86	            assertThat(commanding.deadlineAt()).isEqualTo(expected);
