        return rows.stream().findFirst();
    }

    /** 按机构行 id 查询机构行（回执重放后回查机构与通报归属用）。 */
    public Optional<AgencyNotification> findAgencyById(long agencyNotificationId) {
        List<AgencyNotification> rows = jdbc.query(
