                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"" + key() + "\",\"agencyKey\":\"yi\","
                                + "\"signer\":\"wang\",\"content\":\"yi 回执\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.acknowledgedCount").value(2));
